using SimplePZMapmaker.Core;
static class IntegrationQualityTests {
 public static IEnumerable<(string,Action)> Cases(){
  yield return("new behavior and shared-world data serialize with explicit newer formats",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Version=6;p.StaticModels.Add(new(){ModelId="Base.BeerBottle",X=20,Y=20,Profile="container"});ProjectValidator.Validate(p);var json=System.Text.Json.JsonSerializer.SerializeToElement(p,SimplePZMapmaker.Core.Export.NativeMapExporter.JsonOptions);Check(json.GetProperty("version").GetInt32()==7,"Old editors could discard model behavior");p.StaticModels.Clear();Check(p.Version==6,"Legacy models unexpectedly upgraded");var w=WorldTests.Fixture(2);Check(w.Version==1,"Old world unexpectedly upgraded");var b=HousingTemplates.Create("village-izba");b.X=25850;b.Y=25680;w.Buildings.Add(b);WorldAssembler.Validate(w);Check(System.Text.Json.JsonSerializer.SerializeToElement(w,SimplePZMapmaker.Core.Export.NativeMapExporter.JsonOptions).GetProperty("version").GetInt32()==2,"Old editors could discard shared buildings");});
  yield return("native world preview accepts clipped signed floors after validating whole building",()=>{var w=WorldTests.Fixture(2);var b=HousingTemplates.Create("village-izba");b.X=25850;b.Y=25680;w.Buildings.Add(b);WorldAssembler.Validate(w);var scene=SimplePZMapmaker.Core.Export.NativeScene.WorldCell(w,w.Maps[1].Id,0,64,-1);Check(scene.Sprites.Count>0&&scene.MinLevel==-1,"Clipped basement preview lost");});
  yield return("native model collision sprite belongs to dependency resource set",()=>{var p=MapGenerator.Generate(new(){Kind="blank"});p.Version=6;p.StaticModels.Add(new(){ModelId="Base.BeerBottle",X=20,Y=20,Profile="obstacle"});Check(SimplePZMapmaker.Core.Export.NativeScene.ResourceIds(p).Contains("invisible_01_0"),"Collision sprite provider omitted");});
  yield return("seam repair preserves manually painted ground and reports blocked joins",()=>{var w=WorldTests.Fixture(2);w.Maps[0].Project.Terrain[20*256+255]=Terrain.Road;var p=w.Maps[1].Project;p.Version=6;TerrainEditMask.Mark(p,20*256);p.Terrain[20*256]=Terrain.Sand;var result=WorldSeams.Repair(w);Check(result.World.Maps[1].Project.Terrain[20*256]==Terrain.Sand&&result.Issues.Any(i=>i.Contains("manual")),"Manual terrain overwritten by seam repair");});
 }
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
}
